def stats(a):
    a=np.asarray(a);a=a[np.isfinite(a)]
    return dict(n=int(a.size),median=float(np.median(a)) if a.size else None,p95=float(np.quantile(a,.95)) if a.size else None,max=float(a.max()) if a.size else None)

def render():
    result=json.loads((RUN/'result.json').read_text(encoding='utf-8'))
    if result['status']!='completed':raise ValueError('Control not completed')
    REPORT.mkdir(parents=True,exist_ok=False);mesh=readnp(INPUT/'mesh.npz');g=readnp(INPUT/'geometry.npz');z=readnp(RUN/'frame-000/state.npz');material=readnp(INPUT/'material.npz');obs=readnp(OBS/'comparison-fields-v2.npz');oi=json.loads((OBS/'summary-v2.json').read_text(encoding='utf-8'));source=json.loads((REPAIR/'audit.json').read_text(encoding='utf-8'));geometry=result['geometry']
    package=json.loads(PACKAGE.read_text(encoding='utf-8'));tf=Transformer.from_crs(package['metadata']['crs_wkt'],oi['observation_grid']['crs'],always_xy=True);x,y=g['x'],g['y'];X,Y=np.meshgrid(x,y);ox,oy=tf.transform(X,Y);ot=Affine(*oi['observation_grid']['transform'][:6]);cc,rr=(~ot)*(ox,oy);shape=obs['observed'].shape;idx=np.floor(rr).astype(int)*shape[1]+np.floor(cc).astype(int);N=obs['observed'].size
    mask=g['mask'];nodes=mesh['pixel_center_nodes'];rows,cols=mesh['pixel_rows'],mesh['pixel_cols']
    def raster(values):
        a=np.full(mask.shape,np.nan);a[rows,cols]=values;return a
    def aggregate(a,support=mask):
        m=support&np.isfinite(a);n=np.bincount(idx[m],minlength=N);v=np.bincount(idx[m],weights=a[m],minlength=N);return np.divide(v,n,out=np.full(N,np.nan),where=n>0).reshape(shape)
    speed=raster(np.linalg.norm(z['u'][nodes,-1],axis=1));pred=aggregate(speed);ux=aggregate(raster(z['u'][nodes,-1,0]));uy=aggregate(raster(z['u'][nodes,-1,1]));mag=np.hypot(ux,uy);fraction=aggregate(mask.astype(float),np.ones(mask.shape,bool));core=(fraction>=.5)&obs['valid']&np.isfinite(pred)
    nc=np.bincount(idx[mask],minlength=N).reshape(shape);ne=np.bincount(idx[g['strict_material_coverage']],minlength=N).reshape(shape);strict=core&(nc==ne)
    previous=core&(obs['lia_fraction']>=.5)&(obs['modern_fraction']>=.5)
    reliable=core&np.isfinite(obs['error'])&(obs['error']>0)&(obs['observed']>2*obs['error'])&(mag>0)
    cosine=(ux*obs['observed_direction_x']+uy*obs['observed_direction_y'])/np.maximum(mag,1e-300);angle=np.degrees(np.arccos(np.clip(cosine,-1,1)));angle[~reliable]=np.nan
    ratio=np.divide(pred,obs['observed'],out=np.full(shape,np.nan),where=core&(obs['observed']>0));junction=core&(np.hypot(obs['local_x']+134.49697636368546,obs['local_y']-3158715.5030236365)<=240)
    def compare(m):return dict(observed=stats(obs['observed'][m]),model=stats(pred[m]),cellwise_speed_ratio=stats(ratio[m]),above1000_observed_cells=int(np.sum(obs['observed'][m]>1000)),above1000_model_cells=int(np.sum(pred[m]>1000)))
    subsets=dict(full_modern=compare(core),exact_material_only=compare(strict),previous_shared_support=compare(previous),junction240m=compare(junction));members=[]
    for k,rgi in enumerate(IDS,1):
        f=aggregate((g['member']==k).astype(float),np.ones(mask.shape,bool));m=core&(f>=.5);members.append(dict(rgi=rgi,**compare(m)))
    peak=result['peak_node'];px,py=mesh['xy'][peak];pr=int(np.clip(round((py-y[0])/(y[1]-y[0])),0,len(y)-1));pc=int(np.clip(round((px-x[0])/(x[1]-x[0])),0,len(x)-1));peak_info=dict(node=peak,xy_m=[float(px),float(py)],H_m=result['peak_H_m'],speed_m_year=result['max_speed_m_year'],A_source_distance_m=float(material['distance_m'][peak]),inside_original_material_support=bool(material['exact_coordinate'][peak]),nearest_pixel_member=int(g['member'][pr,pc]))
    summary=dict(status='completed-modern-diagnostic-control',subsets=subsets,members=members,direction_difference_degrees=stats(angle[reliable]),peak=peak_info,geometry=geometry,checks=result['checks'],wall_seconds=result['wall_seconds'],source_repair=source,method=dict(velocity='Arithmetic mean of native model pixel-centre speed magnitudes within each120m observation cell;mean vectors separately used for direction.',coverage='Original F19positive footprint>=50percent. Additional old-overlap and entirely exact-coordinate material subsets reported.',direction='Only positive v_error and v>2*v_error,positive modeled vector magnitude;zero stored errors do not mean zero uncertainty.',time='Modern RGI/F19geometry and DEM are not necessarily synchronous with ITS_LIVE2014-2024 climatology. Model retains prior material assumptions and no-slip bed. This is a modern geometry control,not full calibration or independent validation.',interpretation='Old LIA geometry speeds and modern geometry speeds differ in geometry/footprint/source bed. This result cannot by itself prove correctness of all BP operators or directly correct the LIA reconstruction.'),scientific_acceptance=False)
    write_json(REPORT/'summary.json',summary);np.savez_compressed(REPORT/'comparison-fields.npz',predicted=pred,observed=obs['observed'],core=core,strict_material=strict,previous_shared=previous,ratio=ratio,angle=angle,modern_fraction=fraction,local_x=obs['local_x'],local_y=obs['local_y'],native_speed=speed,modern_H=g['thickness'],x=x,y=y)
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from matplotlib.colors import LogNorm,TwoSlopeNorm
    from matplotlib.font_manager import FontProperties
    plt.rcParams.update({'font.family':FontProperties(fname='C:/Windows/Fonts/msyh.ttc').get_name(),'axes.unicode_minus':False});origin=y.min();lx=obs['local_x']/1000;ly=(obs['local_y']-origin)/1000
    fig,axs=plt.subplots(2,2,figsize=(12,10),constrained_layout=True);vmax=max(float(np.nanmax(pred[core])),float(np.nanmax(obs['observed'][core])),1.)
    for ax,field,title in zip(axs.ravel()[:2],[obs['observed'],pred],['现代卫星速度','原始F19现代几何＋BP']):
        im=ax.pcolormesh(lx,ly,np.where(core,np.maximum(field,.01),np.nan),shading='nearest',cmap='viridis',norm=LogNorm(.01,vmax));fig.colorbar(im,ax=ax,label='米/年');ax.set(title=title,aspect='equal',xlabel='投影东向（km）',ylabel='相对北向（km）')
    logratio=np.log10(np.where(ratio>0,ratio,np.nan));limit=max(1.,float(np.nanmax(abs(logratio[core]))));im=axs[1,0].pcolormesh(lx,ly,logratio,shading='nearest',cmap='RdBu_r',norm=TwoSlopeNorm(vmin=-limit,vcenter=0,vmax=limit));fig.colorbar(im,ax=axs[1,0],label='log10（模型/观测）');axs[1,0].set(title='红：偏快；蓝：偏慢',aspect='equal',xlabel='投影东向（km）',ylabel='相对北向（km）')
    im=axs[1,1].pcolormesh(lx,ly,angle,shading='nearest',cmap='magma',vmin=0,vmax=180);fig.colorbar(im,ax=axs[1,1],label='度');axs[1,1].set(title='流向差：仅有正误差估计的高信噪比像元',aspect='equal',xlabel='投影东向（km）',ylabel='相对北向（km）');fig.suptitle('现代对照 · 相同120米统计尺度 · 速度下限0.01仅用于显示');fig.savefig(REPORT/'velocity.png',dpi=135);plt.close(fig)
    legacy=readnp(PROJECT/'polim_cpu/lia-inputs-v1/system-2387/modern-bp-control-v1/geometry.npz');extent=[(x[0]-(x[1]-x[0])/2)/1000,(x[-1]+(x[1]-x[0])/2)/1000,(y[-1]+(y[1]-y[0])/2-origin)/1000,(y[0]-(y[1]-y[0])/2-origin)/1000]
    fig,axs=plt.subplots(1,3,figsize=(15,5),constrained_layout=True);hm=max(float(np.nanmax(legacy['thickness'])),float(np.nanmax(g['thickness'])))
    for ax,H,title in zip(axs[:2],[np.where(legacy['modern_mask'],legacy['thickness'],np.nan),g['thickness']],['旧系统总冰量校准后的厚度','原始成员F19空间厚度']):
        im=ax.imshow(H,extent=extent,origin='upper',cmap='Blues',vmin=0,vmax=hm);fig.colorbar(im,ax=ax,label='米');ax.set(title=title,xlabel='投影东向（km）',ylabel='相对北向（km）')
    im=axs[2].imshow(np.where(mask,g['member'],np.nan),extent=extent,origin='upper',cmap='Set2',vmin=.5,vmax=3.5);cb=fig.colorbar(im,ax=axs[2],ticks=[1,2,3]);cb.ax.set_yticklabels([i.replace('RGI60-','') for i in IDS]);axs[2].set(title='三个现代成员，保留实际独立边界',xlabel='投影东向（km）',ylabel='相对北向（km）');fig.suptitle('总冰量相近不代表成员冰量和厚度分布正确');fig.savefig(REPORT/'geometry.png',dpi=140);plt.close(fig)
    profiles=json.loads((OBS/'profiles-v2.json').read_text(encoding='utf-8'));fig,axs=plt.subplots(2,4,figsize=(16,7),constrained_layout=True);branches=[]
    for ax,p in zip(axs.ravel(),profiles):
        xx,yy=tf.transform(np.asarray(p['x']),np.asarray(p['y']));cc,rr=(~ot)*(xx,yy);cc=np.floor(cc).astype(int);rr=np.floor(rr).astype(int);d=np.asarray(p['station_m'])/1000;ok=core[rr,cc];ov=np.where(ok,obs['observed'][rr,cc],np.nan);mv=np.where(ok,pred[rr,cc],np.nan)
        ax.step(d,np.maximum(ov,.001),where='mid',label='现代观测',color='#0369a1');ax.plot(d,np.maximum(mv,.001),label='现代BP',color='#c2410c');ax.set(title='原路径 '+str(p['branch']),yscale='log',ylim=(.001,max(1000,vmax*1.1)),xlabel='沿原路径距离（km）',ylabel='米/年');ax.grid(alpha=.2);branches.append(dict(branch=p['branch'],observed=stats(ov),modern_model=stats(mv),samples=int(ok.sum())))
    axs[0,0].legend(fontsize=8);fig.suptitle('沿已有8条路径查看现代共同覆盖 · 路径仍是古冰川网络；空白处不在现代共同范围');fig.savefig(REPORT/'branches.png',dpi=140);plt.close(fig);write_json(REPORT/'branches.json',branches)
    full=subsets['full_modern'];shared=subsets['previous_shared_support'];data=dict(summary=summary,images=['velocity.png','geometry.png','branches.png']);(REPORT/'data.js').write_text('window.MODERN_DATA='+json.dumps(data,ensure_ascii=False,allow_nan=False)+';',encoding='utf-8')
    table=''.join(f'<tr><td>{a}</td><td>{full["observed"][k]:.3g}</td><td>{full["model"][k]:.3g}</td></tr>' for a,k in [('中位数','median'),('第95百分位','p95'),('最大值','max')])
    rows=''.join(f'<tr><td>{r["rgi"].replace("RGI60-","")}</td><td>{r["reference_volume_m3"]/1e6:.3f}</td><td>{r["legacy_volume_m3"]/1e6:.3f}</td><td>{r["legacy_to_reference_ratio"]:.4f}</td></tr>' for r in source['members'])
    html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>现代几何 BP 流速对照</title><style>*{box-sizing:border-box}body{font-family:Microsoft YaHei,sans-serif;background:#edf3f6;color:#183344;margin:0}main{max-width:1400px;margin:auto;padding:28px}p{line-height:1.8}.panel{background:white;border-radius:14px;padding:22px;margin:18px 0}.controls{display:flex;gap:10px;flex-wrap:wrap}button{border:0;background:#176993;color:white;padding:12px 18px;border-radius:8px;cursor:pointer}img{width:100%;height:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid #e0e9ee;padding:10px}.note{font-size:13px;color:#607484}a{color:#116a98}@media(max-width:700px){main{padding:12px}.panel{padding:14px}th,td{font-size:12px;padding:5px}}</style><main><h1>2387 · 现代几何 BP 对照</h1><p>已完成一次固定几何速度求解。采用原始 Farinotti 成员厚度、现代冰面和现有材料参数；底部无滑移。</p><div class="panel"><h2>先修正了一处明确的输入错误</h2><p>旧流程只匹配整个系统的总冰量，却未约束各成员冰量。15.04811 号成员只获得参考冰量的约千分之一；主成员的冰厚也过度集中。现在直接使用原始空间厚度，保留旧版本。</p><table><tr><th>现代成员</th><th>参考冰量（百万m³）</th><th>旧分配冰量（百万m³）</th><th>旧值/参考</th></tr>SOURCE_TABLE</table></div><div class="panel"><h2>实际流速结果</h2><p id="outcome"></p><table><tr><th>米/年</th><th>现代观测</th><th>现代几何 BP</th></tr>SPEED_TABLE</table><p id="tail"></p><p id="support" class="note"></p><p class="note">现代结果与古几何结果不属于同一几何条件。原始 F19 厚度是估计产品；材料沿用此前假设，尚未针对现代冰温或底滑校准，不能把这次对照等同于模型全面验证。</p></div><div class="panel"><div class="controls"><button data-view="0" id="speed">速度对照</button><button data-view="1" id="geometry">冰厚来源</button><button data-view="2" id="branches">分支对照</button></div><h2 id="viewTitle"></h2><img id="map" alt="现代几何速度与观测对照"></div><details class="panel"><summary>数据、材料与计算说明</summary><p>25米原始F19厚度投影到15.75米网格；三角网格采用共同节点，现代分离成员保持分离。每个成员的重投影冰量变化独立记录，没有再强制缩放总量。源字段、原始旧几何和此前结果均保留。</p><p id="material"></p><p id="solve"></p><p>统计采用独立120米观测像元；流速是其中模型像元中心速度大小的平均。方向另用平均速度向量，且只显示观测误差大于零、速度大于两倍误差的像元。原始零误差不解释为零不确定度。现代DEM、RGI边界、F19厚度与2014—2024流速气候态并非严格同年。</p><p><a href="summary.json">完整统计与来源</a> · <a href="comparison-fields.npz">空间数据</a> · <a href="../surface-first-geometry-v1/index.html">之前的古几何试算</a> · <a href="../../index.html">项目首页</a></p></details></main><script src="data.js"></script><script>const D=window.MODERN_DATA,S=D.summary,$=id=>document.getElementById(id),F=S.subsets.full_modern;const titles=['现代观测与现代几何 BP','原始厚度与旧反演分配','沿已有8条路径的现代对照'];function show(i){$('map').src=D.images[i];$('viewTitle').textContent=titles[i]}['speed','geometry','branches'].forEach((id,i)=>$(id).onclick=()=>show(i));$('outcome').textContent='原生模型最高速度 '+S.peak.speed_m_year.toFixed(1)+' 米/年；同尺度共同范围中位数：观测 '+F.observed.median.toFixed(2)+'、模型 '+F.model.median.toFixed(2)+' 米/年。';$('tail').textContent='共同范围超过1000米/年：模型 '+F.above1000_model_cells+' 个像元，观测 '+F.above1000_observed_cells+' 个。1000仅为描述阈值，不是通用速度上限。';$('support').textContent='现代共同范围 '+F.model.n+' 个独立像元；其中完全位于原材料坐标覆盖内 '+S.subsets.exact_material_only.model.n+' 个；与此前比较范围重合 '+S.subsets.previous_shared_support.model.n+' 个。';$('material').textContent='材料值按原网格位置转移：'+S.geometry.exact_material_nodes+' 个节点位置匹配；'+S.geometry.extended_material_nodes+' 个节点用最近位置延用，最大距离 '+S.geometry.maximum_material_extension_m.toFixed(1)+' 米。两种覆盖的统计单独报告。';$('solve').textContent='BP收敛残差 '+S.checks.relative_residual.toExponential(2)+'；求解耗时 '+(S.wall_seconds/60).toFixed(2)+' 分钟；固定几何，无时间演化。';show(0);</script></html>'''
    (REPORT/'index.html').write_text(html.replace('SOURCE_TABLE',rows).replace('SPEED_TABLE',table),encoding='utf-8');write_json(REPORT/'delivery.json',dict(status='completed',result_sha256=digest(RUN/'result.json'),report_code_sha256=digest(Path(__file__)),files={q.relative_to(REPORT).as_posix():digest(q) for q in REPORT.rglob('*') if q.is_file()}));print(json.dumps(dict(subsets=subsets,peak=peak_info,direction=summary['direction_difference_degrees']),ensure_ascii=False),flush=True)

